import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
public class Lab05 {
  static String fallback(AtomicInteger calls) {
    calls.incrementAndGet(); return "fallback";
  }
  public static void main(String[] args) {
    AtomicInteger calls = new AtomicInteger();
    String eager = Optional.of("saved").orElse(fallback(calls));
    String lazy = Optional.of("saved").orElseGet(() -> fallback(calls));
    if (calls.get() != 1 || !eager.equals(lazy)) throw new AssertionError();
    String missing = Optional.<String>empty().orElseGet(() -> fallback(calls));
    if (calls.get() != 2 || !missing.equals("fallback"))
      throw new AssertionError();
    System.out.println("calls=" + calls.get());
  }
}
