import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
public class Lab15 {
  public static void main(String[] args) throws Exception {
    Semaphore slots = new Semaphore(2);
    AtomicInteger active = new AtomicInteger(), peak = new AtomicInteger();
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
      List<Future<Integer>> tasks = new ArrayList<>();
      for (int i=0;i<10;i++) {
        final int n=i;
        tasks.add(executor.submit(() -> {
          if (!Thread.currentThread().isVirtual()) throw new AssertionError();
          slots.acquire();
          try {
            peak.accumulateAndGet(active.incrementAndGet(),Math::max);
            Thread.sleep(1); return n*n;
          } finally { active.decrementAndGet(); slots.release(); }
        }));
      }
      int sum=0;
      for (var task:tasks) sum+=task.get();
      if (sum!=285 || peak.get()>2 || active.get()!=0) throw new AssertionError();
      System.out.println("sum="+sum+"; resourceLimit=2");
    }
  }
}
EXPECTED OUTPUT
sum=285; resourceLimit=2
HOW THE SOLUTION WORKS
The semaphore bounds the protected region, not thread creation or a general backlog. The checked output
avoids promising an exact scheduling order or exact peak of two.
TRY NEXT
Add a failed task and inspect cleanup. Then design bounded admission and deadlines;
do not submit an unbounded production backlog.
