import java.util.*;
public class OddEven {
  final Object lock = new Object();
  final List<Integer> values = new ArrayList<>();
  int next = 1;
  boolean cancelled;
  void emit(int parity) {
    synchronized (lock) {
      try {
        while (!cancelled && next <= 20) {
          while (!cancelled && next <= 20 && next % 2 != parity)
            lock.wait();
          if (cancelled || next > 20) break;
          values.add(next++); lock.notifyAll();
        }
      } catch (InterruptedException e) {
        cancelled = true; Thread.currentThread().interrupt();
      } finally { lock.notifyAll(); }
    }
  }
  public static void main(String[] args) throws Exception {
    OddEven s = new OddEven();
    Thread odd = new Thread(() -> s.emit(1));
    Thread even = new Thread(() -> s.emit(0));
    odd.setDaemon(true); even.setDaemon(true);
    odd.start(); even.start(); odd.join(5000); even.join(5000);
    if (odd.isAlive() || even.isAlive()) {
      odd.interrupt(); even.interrupt(); throw new AssertionError("timeout");
    }
    if (s.values.size() != 20) throw new AssertionError();
    for (int i = 0; i < 20; i++)
      if (s.values.get(i) != i + 1) throw new AssertionError();
    System.out.println("ordered output: 1 through 20");
  }
}
