import java.util.concurrent.*;
public class CancelDemo {
  public static void main(String[] args) throws Exception {
    CountDownLatch entered = new CountDownLatch(1);
    CountDownLatch neverReleased = new CountDownLatch(1);
    CountDownLatch cleaned = new CountDownLatch(1);
    Thread worker = new Thread(() -> {
      try { entered.countDown(); neverReleased.await(); }
      catch (InterruptedException expected) {
        // Top-level worker consumes cancellation and exits.
      } finally { cleaned.countDown(); }
    });
    worker.setDaemon(true); worker.start();
    try {
      if (!entered.await(5, TimeUnit.SECONDS)) throw new AssertionError();
      worker.interrupt();
      if (!cleaned.await(5, TimeUnit.SECONDS)) throw new AssertionError();
      worker.join(5000);
      if (worker.isAlive()) throw new AssertionError();
      System.out.println("cancelled; cleanup completed; worker terminated");
    } finally { worker.interrupt(); }
  }
}
