import java.util.concurrent.*;
public class PoolRejection {
  public static void main(String[] args) throws Exception {
    CountDownLatch entered = new CountDownLatch(1);
    CountDownLatch gate = new CountDownLatch(1);
    ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 1, 0,
        TimeUnit.SECONDS, new ArrayBlockingQueue<>(1),
        new ThreadPoolExecutor.AbortPolicy());
    try {
      Future<?> first = pool.submit(() -> {
        entered.countDown();
        try { gate.await(); }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); }
      });
      if (!entered.await(5, TimeUnit.SECONDS)) throw new AssertionError();
      Future<Integer> second = pool.submit(() -> 42);
      boolean rejected = false;
      try { pool.submit(() -> 99); }
      catch (RejectedExecutionException expected) { rejected = true; }
      if (!rejected) throw new AssertionError();
      gate.countDown(); first.get(5, TimeUnit.SECONDS);
      if (second.get(5, TimeUnit.SECONDS) != 42) throw new AssertionError();
      System.out.println("third task rejected; accepted tasks completed");
    } finally {
      gate.countDown(); pool.shutdownNow();
      if (!pool.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError();
    }
  }
}
