import java.util.concurrent.*;
public class QueuePipeline {
  record Item(int value, boolean stop) {}
  public static void main(String[] args) throws Exception {
    BlockingQueue<Item> queue = new ArrayBlockingQueue<>(2);
    ExecutorService pool = Executors.newFixedThreadPool(2);
    try {
      Future<Integer> consumer = pool.submit(() -> {
        int sum = 0;
        while (true) {
          Item item = queue.take();
          if (item.stop()) return sum;
          sum += item.value();
        }
      });
      Future<?> producer = pool.submit(() -> {
        for (int i = 1; i <= 100; i++) queue.put(new Item(i, false));
        queue.put(new Item(0, true));
        return null;
      });
      producer.get(5, TimeUnit.SECONDS);
      if (consumer.get(5, TimeUnit.SECONDS) != 5050) throw new AssertionError();
      System.out.println("100 items consumed; sum=5050");
    } finally {
      pool.shutdownNow();
      if (!pool.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError();
    }
  }
}
