import java.util.*;
import java.util.concurrent.*;
public class VirtualBudget {
  public static void main(String[] args) throws Exception {
    Semaphore permits = new Semaphore(4);
    List<Future<Integer>> tasks = new ArrayList<>();
    try (ExecutorService executor =
        Executors.newVirtualThreadPerTaskExecutor()) {
      for (int i = 0; i < 20; i++) {
        final int value = i;
        tasks.add(executor.submit(() -> {
          if (!Thread.currentThread().isVirtual()) throw new AssertionError();
          permits.acquire();
          try {
            Thread.sleep(10); // synthetic wait, not a service benchmark
            return value * 2;
          } finally { permits.release(); }
        }));
      }
      int total = 0;
      for (Future<Integer> task : tasks)
        total += task.get(5, TimeUnit.SECONDS);
      if (total != 380 || permits.availablePermits() != 4)
        throw new AssertionError();
      System.out.println("virtual task sum=380");
    }
  }
}
