import java.lang.invoke.*;
public class ReleaseAcquire {
  int payload;
  boolean ready;
  static final VarHandle READY;
  static {
    try {
      READY = MethodHandles.lookup().findVarHandle(
          ReleaseAcquire.class, "ready", boolean.class);
    } catch (ReflectiveOperationException e) {
      throw new ExceptionInInitializerError(e);
    }
  }
  public static void main(String[] args) throws Exception {
    ReleaseAcquire s = new ReleaseAcquire();
    Thread writer = new Thread(() -> {
      s.payload = 42; READY.setRelease(s, true);
    });
    writer.start();
    long deadline = System.nanoTime() + 5_000_000_000L;
    boolean acquired;
    do {
      acquired = (boolean) READY.getAcquire(s);
      if (acquired) break;
      Thread.onSpinWait();
    } while (System.nanoTime() < deadline);
    if (!acquired || s.payload != 42) throw new AssertionError();
    writer.join();
    System.out.println("release/acquire payload=42");
  }
}
