import java.util.ArrayDeque;
public class GcLoad {
    static volatile long checksum;
    public static void main(String[] args) {
        var retained = new ArrayDeque<byte[]>();
        long started = System.nanoTime();
        for (int i = 0; i < 30000; i++) {
            byte[] data = new byte[8192];
            data[0] = (byte) i;
            retained.addLast(data);
            if (retained.size() > 128) {
                checksum += retained.removeFirst()[0];
            }
        }
        if (retained.size() != 128) throw new AssertionError();
        long elapsed = System.nanoTime() - started;
        System.out.println("PASS: bounded allocation workload");
        System.out.println("elapsed_ns=" + elapsed);
        System.out.println("checksum=" + checksum);
    }
}
