import java.lang.management.ManagementFactory;
import java.util.concurrent.CountDownLatch;
public class DeadlockDemo {
    public static void main(String[] args) throws Exception {
        Object a = new Object(), b = new Object();
        var acquired = new CountDownLatch(2);
        Thread t1 = worker(a, b, acquired);
        Thread t2 = worker(b, a, acquired);
        t1.start(); t2.start();
        var bean = ManagementFactory.getThreadMXBean();
        long[] ids = null;
        for (int i = 0; i < 100 && ids == null; i++) {
            Thread.sleep(10);
            ids = bean.findDeadlockedThreads();
        }
        if (ids == null || ids.length != 2)
            throw new AssertionError("expected two-thread deadlock");
        System.out.println("PASS: two deadlocked daemon threads detected");
    }
    static Thread worker(Object first, Object second,
                         CountDownLatch acquired) {
        Thread t = new Thread(() -> {
            synchronized (first) {
                acquired.countDown();
                try { acquired.await(); }
                catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); return;
                }
                synchronized (second) { }
            }
        });
        t.setDaemon(true); return t;
    }
}
