What changes for a streaming text source?
Keep the KMP prefix table and current matched-prefix length between chunks. Process each new character
without resetting the matcher; maintain an absolute stream position to report matches, including those
crossing a chunk boundary.
JAVA 17 · SOLUTION Source Q019 · 16 lines
static List<Integer> occurrences(String text, String pattern) {
  List<Integer> result = new ArrayList<>(); int m = pattern.length();
  if (m == 0) { for (int i=0; i<=text.length(); i++) result.add(i); return result; }
  int[] prefix = new int[m];
  for (int i=1, j=0; i<m; i++) {
    while (j>0 && pattern.charAt(i)!=pattern.charAt(j)) j=prefix[j-1];
    if (pattern.charAt(i)==pattern.charAt(j)) j++;
    prefix[i]=j;
  }
  for (int i=0, j=0; i<text.length(); i++) {
    while (j>0 && text.charAt(i)!=pattern.charAt(j)) j=prefix[j-1];
    if (text.charAt(i)==pattern.charAt(j)) j++;
    if (j==m) { result.add(i-m+1); j=prefix[j-1]; }
  }
  return result;
}
