When might recursion overflow the stack?
Recursive flood fill uses one call per path step and can overflow the JVM stack on a large connected grid.
Iterative BFS or DFS with a queue/stack stores work on the heap and avoids deep recursive calls.
JAVA 17 · SOLUTION Source Q050 · 16 lines
static void floodFill(int[][] a,int row,int col,int color) {
  int cols=columns(a);
  if(row<0 || row>=a.length || col<0 || col>=cols) throw new IllegalArgumentException();
  int old=a[row][col]; if(old==color) return;
  Deque<int[]> queue=new ArrayDeque<>(); queue.add(new int[]{row,col}); a[row][col]=color;
  int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
  while(!queue.isEmpty()) {
    int[] cell=queue.remove();
    for(int[] d:dirs) {
      int r=cell[0]+d[0],c=cell[1]+d[1];
      if(r>=0 && r<a.length && c>=0 && c<cols && a[r][c]==old) {
        a[r][c]=color; queue.add(new int[]{r,c});
      }
    }
  }
}
