How would infix parsing introduce precedence?
Convert infix tokens to postfix with an operator stack, or use a precedence-aware parser. Multiplication
binds more tightly than addition; parentheses override the default order and unary operators need their
own rules.
JAVA 17 · SOLUTION Source Q055 · 20 lines
static int rpn(String[] tokens) {
  Deque<Integer> stack=new ArrayDeque<>();
  for(String token:tokens) {
    if(Set.of("+","-","*","/").contains(token)) {
      if(stack.size()<2) throw new IllegalArgumentException();
      int b=stack.pop(),a=stack.pop(),r;
      switch(token) {
        case "+": r=Math.addExact(a,b); break;
        case "-": r=Math.subtractExact(a,b); break;
        case "*": r=Math.multiplyExact(a,b); break;
        default:
          if(a==Integer.MIN_VALUE && b==-1) throw new ArithmeticException("overflow");
          r=a/b;
      }
      stack.push(r);
    } else stack.push(Integer.parseInt(token));
  }
  if(stack.size()!=1) throw new IllegalArgumentException();
  return stack.pop();
}
