static List<Integer> mergeK(List<List<Integer>> lists) {
  record Cursor(int value,int list,int index) {}
  PriorityQueue<Cursor> heap=new PriorityQueue<>(Comparator.comparingInt(Cursor::value));
  for(int i=0;i<lists.size();i++) if(!lists.get(i).isEmpty())
    heap.offer(new Cursor(lists.get(i).get(0),i,0));
  List<Integer> out=new ArrayList<>();
  while(!heap.isEmpty()) {
    Cursor c=heap.poll(); out.add(c.value()); int next=c.index()+1;
    if(next<lists.get(c.list()).size())
      heap.offer(new Cursor(lists.get(c.list()).get(next),c.list(),next));
  }
  return out;
}
