static void parenthesesDFS(int n,int open,int close,StringBuilder path,List<String> out) {
  if(close==n) { out.add(path.toString()); return; }
  if(open<n) { path.append('('); parenthesesDFS(n,open+1,close,path,out); 
path.setLength(path.length()-1); }
  if(close<open) {
    path.append(')'); parenthesesDFS(n,open,close+1,path,out);
    path.setLength(path.length()-1);
  }
}
