JwtAuthenticationConverter converter() {
  JwtGrantedAuthoritiesConverter scopes = new JwtGrantedAuthoritiesConverter();
  JwtAuthenticationConverter out = new JwtAuthenticationConverter();
  out.setJwtGrantedAuthoritiesConverter(jwt -> {
    List<GrantedAuthority> granted = new ArrayList<>(scopes.convert(jwt));
    List<String> roles = jwt.getClaimAsStringList("roles");
    if (roles != null && roles.contains("ADMIN"))
      granted.add(new SimpleGrantedAuthority("ROLE_ADMIN"));
    return granted;
  });
  return out;
}
// Wire with jwt(j -> j.jwtAuthenticationConverter(converter())).
VERIFICATION AND BOUNDARY POLICY
This trusts ADMIN only if the issuer is authoritative for that application role and the client/grant
policy permits it. Check scope preservation, absent roles, disallowed roles, malformed claim types,
and every trusted issuer separately. Do not map an arbitrary client-controlled role into an
administrator privilege.
