L03. Check a remaining deadline without
overflow
This is the original Java model fragment placed inside the attached teaching runner. The
corresponding test checks are in the download bundle.
static final class Deadline {
private final LongSupplier clock;
private final long started, budget;
Deadline(Duration duration, LongSupplier clock) {
this.clock = Objects.requireNonNull(clock);
this.budget = duration.toNanos();
if (budget <= 0) throw new IllegalArgumentException("budget");
this.started = clock.getAsLong();
}
long remainingNanos() {
long elapsed = clock.getAsLong() - started;
if (elapsed < 0) throw new IllegalStateException("clock");
return elapsed >= budget ? 0 : budget - elapsed;
}
boolean canFit(long workNanos, long delayNanos) {
if (workNanos <= 0 || delayNanos < 0)
throw new IllegalArgumentException("attempt");
long remaining = remainingNanos();
return delayNanos <= remaining
&& workNanos <= remaining - delayNanos;
}
}
