static long jitterDelayMs(int retryNumber, long baseMs,
long capMs, double randomUnit) {
if (retryNumber < 1 || retryNumber > 1000 || baseMs < 1
|| capMs < baseMs || capMs > 60_000
|| !(randomUnit >= 0 && randomUnit < 1))
throw new IllegalArgumentException("retry policy");
long ceiling = baseMs;
for (int i = 1; i < retryNumber && ceiling < capMs; i++) {
ceiling = ceiling >= capMs - ceiling
? capMs : ceiling * 2;
}
return (long) (randomUnit * ceiling);
}
