L05. Reserve stock with an optimistic version
This is the original Java model fragment placed inside the attached teaching runner. The
corresponding test checks are in the download bundle.
enum ReserveResult { RESERVED, VERSION_CONFLICT, INSUFFICIENT }
public record Stock(long version, int available) {}
static final class Inventory {
private final AtomicReference<Stock> state;
Inventory(int initial) {
if (initial < 0) throw new IllegalArgumentException("stock");
state = new AtomicReference<>(new Stock(0, initial));
}
Stock snapshot() { return state.get(); }
ReserveResult reserve(long expectedVersion, int quantity) {
if (quantity <= 0) throw new IllegalArgumentException("quantity");
Stock old = state.get();
if (old.version() != expectedVersion)
return ReserveResult.VERSION_CONFLICT;
if (old.available() < quantity)
return ReserveResult.INSUFFICIENT;
Stock next = new Stock(Math.addExact(old.version(), 1),
old.available() - quantity);
return state.compareAndSet(old, next)
? ReserveResult.RESERVED : ReserveResult.VERSION_CONFLICT;
}
}
