enum SagaState {
ACCEPTED, RESERVED, PAYMENT_UNKNOWN, AUTHORIZED,
CONFIRMED, REJECTED
}
static final class Workflow {
private SagaState state = SagaState.ACCEPTED;
synchronized SagaState state() { return state; }
synchronized boolean move(SagaState expected, SagaState next) {
Objects.requireNonNull(expected); Objects.requireNonNull(next);
if (state == next) return false;
if (state != expected) throw new IllegalStateException("stale state");
boolean allowed = switch (state) {
case ACCEPTED -> next == SagaState.RESERVED
|| next == SagaState.REJECTED;
case RESERVED -> next == SagaState.PAYMENT_UNKNOWN
|| next == SagaState.AUTHORIZED || next == SagaState.REJECTED;
case PAYMENT_UNKNOWN -> next == SagaState.AUTHORIZED
|| next == SagaState.REJECTED;
case AUTHORIZED -> next == SagaState.CONFIRMED;
case CONFIRMED, REJECTED -> false;
};
if (!allowed) throw new IllegalStateException("invalid transition");
state = next;
return true;
}
}
