public record View(long version, long total) {}
static final class Projection {
private final Map<String, View> views = new HashMap<>();
synchronized boolean apply(String aggregate, long version, long delta) {
nonBlank(aggregate);
if (version < 1) throw new IllegalArgumentException("version");
View old = views.getOrDefault(aggregate, new View(0, 0));
if (version <= old.version()) return false;
if (version != old.version() + 1)
throw new IllegalStateException("version gap");
View next = new View(version, Math.addExact(old.total(), delta));
views.put(aggregate, next);
return true;
}
synchronized View get(String aggregate) {
return views.getOrDefault(aggregate, new View(0, 0));
}
}
