JAVA 17 CODING LAB C01 COMPILED + EXECUTED
T oken bucket with an injected clock
Full standalone source: Lab01.java · No framework dependencies · `javac --release 17 Lab01.java`
public class Lab01 {
    static final class Bucket {
      final double capacity, perSecond;
      double tokens; long lastNanos;
      Bucket(double capacity, double rate, long now) {
        if (capacity <= 0 || rate <= 0 || !Double.isFinite(capacity)
            || !Double.isFinite(rate)) throw new IllegalArgumentException();
        this.capacity = capacity; perSecond = rate;
        tokens = capacity; lastNanos = now;
      }
      synchronized boolean allow(double cost, long now) {
        if (cost <= 0 || !Double.isFinite(cost))
          throw new IllegalArgumentException();
        if (now < lastNanos) throw new IllegalArgumentException("clock");
        tokens = Math.min(capacity,
            tokens + (now - lastNanos) / 1_000_000_000d * perSecond);
        lastNanos = now;
        if (tokens < cost) return false;
        tokens -= cost; return true;
      }
    }
    public static void main(String[] args) {
      var b = new Bucket(2, 1, 0);
      boolean a = b.allow(1, 0), c = b.allow(1, 0);
      boolean blocked = !b.allow(1, 0);
      boolean refill = b.allow(1, 1_000_000_000L);
      boolean oversized = !b.allow(3, 5_000_000_000L);
      boolean invalid = false;
      try { b.allow(0, 5_000_000_000L); }
      catch (IllegalArgumentException ex) { invalid = true; }
      if (!(a && c && blocked && refill && oversized && invalid))
        throw new AssertionError();
      System.out.println("burst=2; blocked=true; refill=true");
      System.out.println("oversized rejected; zero cost rejected");
    }
  }
VERIFIED OUTPUT
burst=2; blocked=true; refill=true
oversized rejected; zero cost rejected
Practice boundary: This proves the local model's included checks, not a durable multi-node production guarantee. Add
concurrency, failure-injection and integration tests before production use.
