import java.util.*;
  import java.nio.charset.StandardCharsets;
  import java.security.MessageDigest;
  import java.nio.ByteBuffer;
  public class Lab04 {
    static long score(String key, String node) {
      try {
        byte[] hash = MessageDigest.getInstance("SHA-256")
            .digest((key + "\0" + node).getBytes(StandardCharsets.UTF_8));
        return ByteBuffer.wrap(hash).getLong();
      } catch (Exception ex) { throw new IllegalStateException(ex); }
    }
    static String owner(String key, List<String> nodes) {
      if (nodes.isEmpty()) throw new IllegalArgumentException();
      return nodes.stream().max((a,b) -> {
        int c = Long.compareUnsigned(score(key,a), score(key,b));
        return c != 0 ? c : a.compareTo(b);
      }).orElseThrow();
    }
    public static void main(String[] args) {
      var oldNodes = List.of("A", "B", "C");
      var newNodes = List.of("A", "B", "C", "D");
      int moved = 0;
      for (int i = 0; i < 1000; i++) {
        String key = "k" + i;
        String before = owner(key, oldNodes), after = owner(key, newNodes);
        if (!before.equals(after)) {
          moved++;
          if (!after.equals("D")) throw new AssertionError();
        }
        if (!before.equals(owner(key, List.of("C", "A", "B"))))
          throw new AssertionError();
      }
      if (moved == 0 || moved == 1000) throw new AssertionError();
      System.out.println("all moved keys go to D; list order is irrelevant");
    }
  }
