import java.util.concurrent.*;
  public class Lab05 {
    public static void main(String[] args) throws Exception {
      var started = new CountDownLatch(1);
      var release = new CountDownLatch(1);
      var pool = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS,
          new ArrayBlockingQueue<Runnable>(1),
          new ThreadPoolExecutor.AbortPolicy());
      boolean rejected = false;
      Future<Integer> queued = null;
      try {
        pool.execute(() -> {
          started.countDown();
          try { release.await(); }
          catch (InterruptedException ex) { Thread.currentThread().interrupt(); }
        });
        if (!started.await(2, TimeUnit.SECONDS)) throw new AssertionError();
        queued = pool.submit(() -> 7);
        try { pool.submit(() -> 9); }
        catch (RejectedExecutionException ex) { rejected = true; }
        if (!rejected) throw new AssertionError();
      } finally {
        release.countDown(); pool.shutdown();
      }
      if (queued == null || queued.get(2, TimeUnit.SECONDS) != 7)
        throw new AssertionError();
      if (!pool.awaitTermination(2, TimeUnit.SECONDS)) {
        pool.shutdownNow(); throw new AssertionError();
      }
      System.out.println("one running; one queued; third rejected");
      System.out.println("queued work completes after release");
    }
  }
