import java.util.concurrent.*;
  import java.util.concurrent.atomic.AtomicInteger;
  import java.util.function.Supplier;
  public class Lab06 {
    static final class Flights {
      final ConcurrentHashMap<String,CompletableFuture<String>> active =
          new ConcurrentHashMap<>();
      final CountDownLatch joined = new CountDownLatch(1); // test observation
      String get(String key, Supplier<String> loader) {
        var mine = new CompletableFuture<String>();
        var existing = active.putIfAbsent(key, mine);
        if (existing != null) { joined.countDown(); return existing.join(); }
        try {
          String result = loader.get(); mine.complete(result); return result;
        } catch (RuntimeException | Error ex) {
          mine.completeExceptionally(ex); throw ex;
        } finally { active.remove(key, mine); }
      }
    }
    public static void main(String[] args) throws Exception {
      var f = new Flights(); var calls = new AtomicInteger();
      var entered = new CountDownLatch(1); var release = new CountDownLatch(1);
      var pool = Executors.newFixedThreadPool(2);
      try {
        var first = pool.submit(() -> f.get("p", () -> {
          calls.incrementAndGet(); entered.countDown();
          try { release.await(); }
          catch (InterruptedException ex) { throw new RuntimeException(ex); }
          return "value";
        }));
        if (!entered.await(2, TimeUnit.SECONDS)) throw new AssertionError();
        var second = pool.submit(() -> f.get("p", () -> {
          throw new AssertionError("duplicate load");
        }));
        if (!f.joined.await(2, TimeUnit.SECONDS)) throw new AssertionError();
        release.countDown();
        if (!second.get(2, TimeUnit.SECONDS).equals("value") ||
            !first.get(2, TimeUnit.SECONDS).equals("value"))
          throw new AssertionError();
        if (calls.get() != 1 || !f.active.isEmpty()) throw new AssertionError();
        System.out.println("two callers; one load; in-flight entry removed");
      } finally { release.countDown(); pool.shutdownNow(); }
    }
  }
