Local idempotency and conflicting intent
Full standalone source: Lab07.java · No framework dependencies · `javac --release 17 Lab07.java`
import java.util.*;
  public class Lab07 {
    record Request(String customer, String key, long amount) {}
    record Scope(String customer, String key) {}
    record Stored(Request request, String response) {}
    static final class Service {
      final Map<Scope,Stored> completed = new HashMap<>();
      int effects;
      synchronized String apply(Request r) {
        if (r.amount() <= 0) throw new IllegalArgumentException();
        var scope = new Scope(r.customer(), r.key());
        var old = completed.get(scope);
        if (old != null) {
          if (!old.request().equals(r))
            throw new IllegalArgumentException("key reused with new intent");
          return old.response();
        }
        String result = "order-" + (++effects);
        completed.put(scope, new Stored(r, result));
        return result;
      }
    }
    public static void main(String[] args) {
      var s = new Service(); var r = new Request("c1", "k1", 500);
      String a = s.apply(r), b = s.apply(r);
      boolean conflict = false;
      try { s.apply(new Request("c1", "k1", 700)); }
      catch (IllegalArgumentException ex) { conflict = true; }
      String other = s.apply(new Request("c2", "k1", 500));
      if (!a.equals(b) || a.equals(other) || !conflict || s.effects != 2)
        throw new AssertionError();
      System.out.println("retry returns order-1; conflicting intent rejected");
      System.out.println("other caller has a separate scope; effects=2");
    }
  }
