import java.util.concurrent.*;
  import java.util.concurrent.atomic.AtomicInteger;
  public class Lab08 {
    static final class Stock {
      final AtomicInteger available = new AtomicInteger(3);
      boolean reserve(int quantity) {
        if (quantity <= 0) throw new IllegalArgumentException();
        while (true) {
          int old = available.get();
          if (old < quantity) return false;
          if (available.compareAndSet(old, old - quantity)) return true;
        }
      }
    }
    public static void main(String[] args) throws Exception {
      var stock = new Stock(); var wins = new AtomicInteger();
      var start = new CountDownLatch(1);
      var pool = Executors.newFixedThreadPool(8);
      try {
        var tasks = new java.util.ArrayList<Future<?>>();
        for (int i = 0; i < 20; i++) tasks.add(pool.submit(() -> {
          try { start.await(); }
          catch (InterruptedException ex) { throw new RuntimeException(ex); }
          if (stock.reserve(1)) wins.incrementAndGet();
        }));
        start.countDown();
        for (var task : tasks) task.get(2, TimeUnit.SECONDS);
        if (wins.get() != 3 || stock.available.get() != 0)
          throw new AssertionError();
        boolean invalid = false;
        try { stock.reserve(-1); }
        catch (IllegalArgumentException ex) { invalid = true; }
        if (!invalid) throw new AssertionError();
        System.out.println("20 callers; 3 reservations; stock=0");
        System.out.println("negative quantity rejected");
      } finally { start.countDown(); pool.shutdownNow(); }
    }
  }
