Cursor pagination with equal timestamps
Full standalone source: Lab09.java · No framework dependencies · `javac --release 17 Lab09.java`
import java.util.*;
  public class Lab09 {
    record Row(long time, long id) {}
    static final Comparator<Row> ORDER =
        Comparator.comparingLong(Row::time).thenComparingLong(Row::id)
            .reversed();
    static List<Row> page(List<Row> rows, Row cursor, int size) {
      if (size < 1) throw new IllegalArgumentException();
      return rows.stream().filter(r -> cursor == null ||
          r.time() < cursor.time() ||
          (r.time() == cursor.time() && r.id() < cursor.id()))
          .sorted(ORDER).limit(size).toList();
    }
    public static void main(String[] args) {
      var rows = List.of(new Row(10,1), new Row(10,2),
          new Row(10,3), new Row(9,4));
      var first = page(rows, null, 2);
      var second = page(rows, first.get(first.size()-1), 2);
      if (!first.equals(List.of(new Row(10,3), new Row(10,2))))
        throw new AssertionError();
      if (!second.equals(List.of(new Row(10,1), new Row(9,4))))
        throw new AssertionError();
      if (!page(rows, second.get(1), 2).isEmpty()) throw new AssertionError();
      System.out.println("page1 IDs=[3, 2]; page2 IDs=[1, 4]");
      System.out.println("same-time rows are neither skipped nor repeated");
    }
  }
