      var r = new Resource();
      if (!r.write(7, "A-first")) throw new AssertionError();
      if (!r.write(8, "B-current")) throw new AssertionError();
      if (r.write(7, "A-stale")) throw new AssertionError();
      if (!r.value.equals("B-current")) throw new AssertionError();
      if (!r.write(8, "B-next")) throw new AssertionError();
      System.out.println("fence 8 accepted; stale fence 7 rejected");
      System.out.println("same current owner may write again");
    }
  }

pages.fullText:
JAVA 17 CODING LAB C11 COMPILED + EXECUTED
Reservation expiry versus confirmation
Full standalone source: Lab11.java · No framework dependencies · `javac --release 17 Lab11.java`
public class Lab11 {
    enum State { HELD, CONFIRMED, EXPIRED, RELEASED }
    static final class Hold {
      final long expiresAt; State state = State.HELD;
      Hold(long expiresAt) { this.expiresAt = expiresAt; }
      synchronized boolean confirm(long now) {
        if (state == State.CONFIRMED) return true;
        if (state != State.HELD) return false;
        if (now >= expiresAt) { state = State.EXPIRED; return false; }
        state = State.CONFIRMED; return true;
      }
      synchronized boolean expire(long now) {
        if (state == State.HELD && now >= expiresAt) {
          state = State.EXPIRED; return true;
        }
        return false;
      }
    }
    public static void main(String[] args) {
      var timely = new Hold(100);
      if (!timely.confirm(99) || !timely.confirm(101))
        throw new AssertionError();
      if (timely.expire(101)) throw new AssertionError();
      var late = new Hold(100);
      if (late.confirm(100) || late.state != State.EXPIRED)
        throw new AssertionError();
      var swept = new Hold(100);
      if (!swept.expire(100) || swept.confirm(101))
        throw new AssertionError();
      System.out.println("confirmed retry stays confirmed; expiry cannot undo it");
      System.out.println("exact expiry rejects confirmation; sweep wins are final");
    }
  }
VERIFIED OUTPUT
confirmed retry stays confirmed; expiry cannot undo it
exact expiry rejects confirmation; sweep wins are final
Practice boundary: This proves the local model's included checks, not a durable multi-node production guarantee. Add
concurrency, failure-injection and integration tests before production use.
