JAVA WORKED EXAMPLE / FILE 2 OF 4
Health.java
A short-timeout Java HTTP probe that exits 0 for healthy and 1 for unhealthy.
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
public class Health {
    public static void main(String[] args) {
        try {
            String port = System.getenv().getOrDefault("PORT", "8080");
            var client = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(2)).build();
            var request = HttpRequest.newBuilder(
                URI.create("http://127.0.0.1:" + port + "/health"))
                .timeout(Duration.ofSeconds(3)).GET().build();
            var response = client.send(request,
                HttpResponse.BodyHandlers.ofString());
            boolean up = response.statusCode() == 200
                && response.body().equals("UP\n");
            System.out.println(up ? "healthy" : "unhealthy");
            System.exit(up ? 0 : 1);
        } catch (Exception failure) {
            System.out.println("unhealthy");
            System.exit(1);
        }
    }
}
