AWS SDK Java 17 source
Uses SDK v2 default credential chain and headObject to read object metadata.
package interview;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.HeadObjectRequest;
import software.amazon.awssdk.services.s3.model.HeadObjectResponse;
public final class ObjectMetadata {
    public static void main(String[] args) {
        if (args.length != 3) {
            throw new IllegalArgumentException(
                "Usage: ObjectMetadata REGION BUCKET KEY");
        }
        try (S3Client s3 = S3Client.builder()
                .region(Region.of(args[0])).build()) {
            HeadObjectResponse result = s3.headObject(
                HeadObjectRequest.builder()
                    .bucket(args[1]).key(args[2]).build());
            System.out.println("bytes=" + result.contentLength());
            System.out.println("version=" + result.versionId());
        }
    }
}
